#!/usr/bin/env bash
# AKFC — Partenaires du club, incrément 2 : écrans.
#  - Réglages du site → « Partenaires du club » : nom, rôle, présentation, site, liens utiles
#    (ex. inscription/tarifs et activités AKFC sur le site de la MJC), logo (SVG/PNG/WebP/JPEG,
#    aperçu sur fond adapté), visible ou masqué, ordre, ajout, suppression (confirmée).
#  - Pied de page : bandeau des logos partenaires (pastilles claires, lien vers leur site),
#    avec leur rôle (« Lieu des cours et des inscriptions », « Fédération d'affiliation »).
#  - Nouvelle page éditoriale « S'inscrire » (/inscription) : contenu rédigé au constructeur, ou
#    par défaut les 4 étapes (cours à la MJC, inscription et paiement à son accueil, licence FFK
#    proposée par les sifus en début de saison, contact) + « Liens utiles » des partenaires.
#    Entrée « S'inscrire » dans le menu (et donc le pied de page) ; page dans « Pages éditoriales »
#    (BROUILLON tant qu'on ne la publie pas) ; plan du site une fois publiée.
#  - Accueil : l'appel final propose « Comment s'inscrire » + « Nous contacter ».
#  Preuve avant commit : pnpm check (sinon TOUT est restauré).
# Usage : bash apply-site-partners-front.sh   (AKFC_APPLY_ONLY=1 : applique sans vérifier ni committer)
set -euo pipefail
[ -f "package.json" ] || { echo "ERREUR: racine du repo." >&2; exit 1; }
[ -f packages/backend/src/modules/sitePartners/router.ts ] || { echo "ERREUR: applique d'abord apply-site-partners-backend.sh." >&2; exit 1; }
NEW=("apps/web/src/features/partners/partnerUi.ts" "apps/web/src/features/partners/PartnerLogo.tsx" "apps/web/src/features/partners/getActivePartners.ts" "apps/web/src/features/admin/site-settings/PartnersSettings.tsx" "apps/web/src/app/(public)/inscription/page.tsx")
[ -f "apps/web/src/features/admin/site-settings/PartnersSettings.tsx" ] && { echo "— déjà appliqué"; exit 0; }
for f in "${NEW[@]}"; do [ -e "$f" ] && { echo "ERREUR: $f existe déjà." >&2; exit 1; }; done
EDITED=(apps/web/src/config/pageRegistry.ts "apps/web/src/app/(admin)/dashboard/site-pages/[slug]/page.tsx" apps/web/src/features/app-shell/navEntries.ts "apps/web/src/app/(admin)/dashboard/settings/page.tsx" apps/web/src/features/app-shell/Footer.tsx "apps/web/src/app/(public)/page.tsx" apps/web/src/app/sitemap.ts)
BK=/tmp/akfc_spf_backup; rm -rf "$BK"; mkdir -p "$BK"
for f in "${EDITED[@]}"; do [ -f "$f" ] || { echo "ERREUR: $f introuvable." >&2; exit 1; }; mkdir -p "$BK/$(dirname "$f")"; cp "$f" "$BK/$f"; done
restore(){ for f in "${EDITED[@]}"; do cp "$BK/$f" "$f"; done; rm -f "${NEW[@]}"; rmdir apps/web/src/features/partners "apps/web/src/app/(public)/inscription" 2>/dev/null || true; echo "↩ fichiers restaurés à l'identique (aucun commit)."; }
W=/tmp/akfc_spf; rm -rf "$W"; mkdir -p "$W"
echo '' | base64 -d > "$W/edit.py"

echo "== application =="
mkdir -p apps/web/src/features/partners "apps/web/src/app/(public)/inscription"
echo '' | base64 -d > "apps/web/src/features/partners/partnerUi.ts"
echo '' | base64 -d > "apps/web/src/features/partners/PartnerLogo.tsx"
echo '' | base64 -d > "apps/web/src/features/partners/getActivePartners.ts"
echo '' | base64 -d > "apps/web/src/features/admin/site-settings/PartnersSettings.tsx"
echo '' | base64 -d > "apps/web/src/app/(public)/inscription/page.tsx"
echo "  ok  5 fichiers créés"
python3 "$W/edit.py" . || { restore; exit 1; }
if [ "${AKFC_APPLY_ONLY:-0}" = "1" ]; then echo "APPLY_ONLY"; exit 0; fi

echo "== pnpm check =="
if ! pnpm check > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"; grep -nE "conventions Next|error TS|Error:" /tmp/akfc_tc.log | head -15; restore; exit 1
fi
echo "  ✅ check OK"
git add "${NEW[@]}" "${EDITED[@]}"
git commit -F - >/tmp/c.log 2>&1 <<'MSG' && echo "✅ commit $(git rev-parse --short HEAD)" || { echo "commit KO"; tail -3 /tmp/c.log; }
feat(partners): réglages des partenaires, logos en pied de page, page « S'inscrire »

